#include "uros_demo_structure_cpp_pkg/base_headers/proc_joy_base_src.hpp"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

proc_joy_base::proc_joy_base() : Node("proc_joy")
{
    cb_group_ = this->create_callback_group(rclcpp::CallbackGroupType::Reentrant);
    // Setting up connections
    proc_joy_joy_publisher_ = this->create_publisher<sensor_msgs::msg::Joy>(
        "proc_ttj_joy",
        1);

    // timeTriggered callback timer
    periodTimer_ = this->create_wall_timer(std::chrono::milliseconds(100),
        std::bind(&proc_joy_base::timeTriggered, this), cb_group_);

}

//=================================================
//  C o m m u n i c a t i o n
//=================================================

void proc_joy_base::put_joy(sensor_msgs::msg::Joy msg)
{
    proc_joy_joy_publisher_->publish(msg);
}

